// Generates the 7 digital lo-fi wireframes in src/lofi/ (plan/04 §B–C), kept in sync with the FINAL Hi-Fi screens
// (all 1440 × 900, same sidebar everywhere, same layouts). They double as the reference for the paper sketch session,
// so shapes are kept simple enough to draw by hand: boxes, bars, X for images, real labels only on headings/buttons.
// Run: node scripts/build-lofi.mjs (part of npm run generate)
import fs from 'node:fs';

const page = (id, title, route, us, body) => `<!doctype html>
<!-- ${id} · Lo-fi ${title} · ${route} · ${us} -->
<!-- GENERATED by scripts/build-lofi.mjs (matches the final Hi-Fi). Edit the script, then re-run. -->
<html lang="en"><head><meta charset="utf-8"><title>Lo-fi · ${title}</title>
<link href="https://fonts.googleapis.com/css2?family=Kalam:wght@400;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="lofi.css"></head>
<body data-frame="desktop">
${body}
</body></html>
`;

// ---------- drawing primitives ----------
const bar = (w = 100, dark = false, h) => `<div class="bar${dark ? ' bar-dark' : ''}" style="width:${w}%${h ? `;height:${h}px` : ''}"></div>`;
const lines = (...ws) => `<div class="lines">${ws.map((w) => bar(w)).join('')}</div>`;
const pill = (t, extra = '') => `<span class="pill"${extra ? ` style="${extra}"` : ''}>${t}</span>`;
const circle = (t, size = 36) => `<span class="circle" style="width:${size}px;height:${size}px">${t}</span>`;
const btn = (t, cls = '', style = '') => `<span class="btn${cls ? ' ' + cls : ''}"${style ? ` style="${style}"` : ''}>${t}</span>`;
// small chart: dashed lower/upper limit lines with the last readings as connected dots between them
function limitChart(dip = false, stacked = false) { // stacked: inside a column (fixed height instead of flex width)
  const pts = dip ? [[6, 30], [40, 32], [74, 36], [108, 50], [142, 70], [176, 84], [196, 92]] : [[6, 46], [40, 44], [74, 47], [108, 45], [142, 46], [176, 44], [196, 45]];
  return `<div style="position:relative;${stacked ? 'flex:none;width:100%' : 'flex:1'};height:96px;border-top:2px dashed var(--text-muted);border-bottom:2px dashed var(--text-muted);margin:6px 0">
    <svg viewBox="0 0 200 92" preserveAspectRatio="none" style="position:absolute;inset:0;width:100%;height:100%"><path d="M${pts.map((p) => p.join(' ')).join(' L')}" fill="none" stroke="#1C1E21" stroke-width="2.5"/>${pts.map(([x, y]) => `<circle cx="${x}" cy="${y}" r="4" fill="#1C1E21"/>`).join('')}</svg>
  </div>`;
}

// ---------- the one sidebar (same items and order on every screen, like the Hi-Fi) ----------
const NAV = ['Dashboard', 'Live prints', 'Alerts (2)', 'AI suggestions (1)', 'Sessions', 'Achievements', 'Admin [lock]', 'Settings'];
const sidebar = (active) => `<aside class="side">
    <div class="row" style="gap:10px;align-items:center;margin-bottom:6px"><div class="x" style="width:36px;height:36px"></div><span class="h2">PRIME</span></div>
    ${NAV.map((n) => (n.startsWith(active)
    ? `<div class="box box-thin shade" style="padding:6px 12px"><span class="lbl">${n}</span></div>`
    : `<span class="lbl" style="padding:0 12px">${n}</span>`)).join('\n    ')}
    <span class="lbl" style="padding:0 12px;margin-top:auto">Help</span>
    <span class="lbl" style="padding:0 12px">Collapse</span>
  </aside>`;
const userChips = (role, initials) => `${pill('o All sensors live', 'margin-left:auto')}${circle('2', 32)}${pill(role)}${circle(initials)}`;
// top bars: normal pages (title + date | clock) and print pages (job + Live/Vision/Trends/AI tabs)
const topbar = (title, role = 'Engineer', initials = 'DP') => `<div class="topbar">
      <div class="col" style="gap:2px"><span class="h2">${title}</span><span class="note">Fri Oct 9 · Shift B | clock 14:34</span></div>
      <div class="input" style="width:260px;margin-left:24px;height:40px"><span class="note">Search</span></div>
      ${userChips(role, initials)}
    </div>`;
const TABS = ['Live', 'Vision', 'Trends', 'AI'];
const printTop = (tab, role = 'Engineer', initials = 'DP') => `<div class="topbar">
      <div class="col" style="gap:2px"><span class="h2">WP-03 · Gantry-02</span><span class="note">Job #A-1027 | clock 14:34</span></div>
      <div class="row" style="gap:4px;margin-left:24px">${TABS.map((t) => `<span class="tab${t === tab ? ' tab-on' : ''}">${t}</span>`).join('')}</div>
      ${userChips(role, initials)}
    </div>`;
// control bar: identical on every print screen, buttons only (US-07)
const controlBar = `<div class="ctrl">${btn('|| Pause', 'btn-big', 'margin-left:auto')}${btn('&gt; Resume', 'btn-big', 'border-style:dashed')}${btn('[ ] STOP (hold)', 'btn-stop')}</div>`;
const shell = (active, top, main, ctrl = false) => `<div class="row" style="gap:0;height:900px">
  ${sidebar(active)}
  <div class="col grow" style="gap:0">
    ${top}
    ${main}
    ${ctrl ? controlBar : ''}
  </div>
</div>`;
const kpi = (label, value) => `<div class="box grow col" style="gap:6px"><span class="note">${label}</span><span class="h">${value}</span></div>`;

// ---------- L01 · Login + MFA (centered column, logo on top) ----------
const digit = (d = '') => `<div class="box box-thin row center" style="width:50px;height:60px;padding:0;font-size:22px">${d}</div>`;
const authFrame = (route, form) => `<div class="col grow" style="gap:12px">
    <div class="lbl">${route}</div>
    <div class="box shade col" style="flex:1;align-items:center;padding:48px 0 0;gap:0">
      <div class="row center" style="gap:12px"><div class="x" style="width:64px;height:64px"></div><span class="h" style="font-size:34px">PRIME</span></div>
      <div class="bar bar-dark" style="width:200px;margin-top:12px"></div>
      <div class="box col" style="width:400px;margin-top:36px;padding:30px;gap:16px">${form}</div>
      <div class="row center" style="margin-top:20px;gap:8px"><span class="note">[lock] Secured with 2-factor · encrypted</span></div>
    </div>
  </div>`;
const L01 = `<div class="row" style="padding:40px;gap:40px;height:900px">
  ${authFrame('/login', `
        <div class="h">Sign in to PRIME</div>${lines(85)}
        <div class="col" style="gap:6px"><div class="lbl">Email</div><div class="input"></div></div>
        <div class="col" style="gap:6px"><div class="row" style="justify-content:space-between"><span class="lbl">Password</span><span class="note" style="text-decoration:underline">Forgot password?</span></div><div class="input" style="justify-content:flex-end"><span class="note">show</span></div></div>
        <div class="row" style="gap:10px;align-items:center"><span class="chk"></span><span class="note">Remember this device 30 days</span></div>
        <div class="btn btn-fill" style="width:100%">Sign in</div>`)}
  ${authFrame('/login/verify', `
        <div class="note" style="text-decoration:underline">&lt; dev.patel@...</div>
        <div class="h">Check your authenticator app</div>${lines(70)}
        <div class="row" style="gap:8px;justify-content:center">${digit(4)}${digit(8)}${digit(2)}${digit()}${digit()}${digit()}</div>
        <div class="note">(timer) Code expires in 0:24</div>
        <div class="btn btn-fill" style="width:100%">Verify</div>
        <div class="note" style="text-decoration:underline;align-self:center">Use a backup code</div>`)}
</div>`;

// ---------- L02 · Dashboard (minimal: KPIs · printer cards · shift goal) ----------
const kv = (k, v) => `<div class="col" style="gap:2px"><span class="note">${k}</span><span class="lbl" style="font-size:22px">${v}</span></div>`;
function printerCard(name, status, progress, values, buttons, strong = false) {
  const middle = progress
    ? `<div class="col" style="gap:6px"><div class="row" style="justify-content:space-between"><span class="note">Layer ${progress[0]}</span><span class="note">ETA</span></div><div class="bar" style="height:12px"><div class="bar bar-dark" style="width:${progress[1]}%;height:12px"></div></div></div>`
    : `<div class="box box-thin shade col" style="gap:6px;padding:10px"><span class="lbl">Next job: Footing F-2</span>${bar(60)}</div>`;
  return `<div class="box grow col" style="gap:16px;padding:22px${strong ? ';border-width:4px' : ''}">
          <div class="row" style="justify-content:space-between;align-items:center"><span class="h2">${name}</span>${pill(status)}</div>
          ${middle}
          ${values ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px 24px">${values}</div>` : ''}
          <div class="row" style="margin-top:auto;gap:10px">${buttons}</div>
        </div>`;
}
const L02 = shell('Dashboard', topbar('Good afternoon, Dev'), `<div class="col grow" style="padding:36px 44px;gap:30px">
      <div class="row" style="gap:24px">${kpi('Active prints', 2)}${kpi('Open alerts', 2)}${kpi('* AI suggestions', 1)}${kpi('Shift quality', '94 ~~')}</div>
      <div class="row" style="justify-content:space-between"><span class="h2">Printers</span><span class="note" style="text-decoration:underline">View all live prints</span></div>
      <div class="row" style="gap:24px;height:390px">
        ${printerCard('Gantry-02', '! Width −9 %', ['42/120', 35], kv('Temp', '24.6') + kv('Pump', '246') + kv('Speed', '100') + kv('! Width', '36.4'), btn('Open live', 'btn-fill') + btn('Vision'), true)}
        ${printerCard('Arm-01', 'o In range', ['88/96', 92], kv('Temp', '23.1') + kv('Pump', '238') + kv('Speed', '92') + kv('Width', '39.8'), btn('Open live'))}
        ${printerCard('Gantry-03', 'Idle', null, '', btn('Start pre-check'))}
      </div>
      <div class="box row" style="align-items:center;gap:16px"><span class="circle" style="width:30px;height:30px"></span><span class="lbl">Shift B goal: 3 prints with quality ≥ 90</span><div class="bar" style="width:260px;height:12px;margin-left:auto"><div class="bar bar-dark" style="width:67%;height:12px"></div></div><span class="note">2/3</span></div>
    </div>`);

// ---------- L03 · Live Print Monitor (3 × 2 cards: value bottom-left, limit chart right) ----------
const liveCard = (label, value, status, extra = '', dip = false, strong = false) => `<div class="box col" style="gap:4px;padding:16px 18px${strong ? ';border-width:4px' : ''}">
      <div class="row" style="justify-content:space-between"><span class="lbl">${label}</span><span class="note">${status}</span></div>
      <div class="row grow" style="align-items:flex-end;gap:16px">
        <div class="col" style="gap:2px"><span class="h" style="font-size:38px">${value}</span>${extra ? `<span class="lbl">${extra}</span>` : ''}${bar(80)}</div>
        ${limitChart(dip)}
      </div>
    </div>`;
const L03 = shell('Live prints', printTop('Live', 'Operator', 'MO'), `<div class="row" style="gap:12px;align-items:center;padding:12px 24px;border-bottom:2px dashed var(--text)"><span class="lbl">/!\\ Layer width 36.4 mm is below target and dropping</span><span class="note" style="margin-left:auto">0:42 ago</span>${btn('View')}${btn('Acknowledge', 'btn-fill')}</div>
    <div class="col grow" style="padding:16px 24px;gap:14px">
      <div style="display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:1fr 1fr;gap:14px;flex:1">
        ${liveCard('Material temp', '24.6 °C', 'o In range')}
        ${liveCard('Pump speed', '246 RPM', 'o In range')}
        ${liveCard('Pump power', '1.9 kW', 'o In range')}
        ${liveCard('Print speed', '100 mm/s', 'o In range', 'Nozzle Ø 30 mm')}
        ${liveCard('Layer width', '36.4 mm', '! Low −9 %', '', true, true)}
        ${liveCard('Interlayer delay', '132 s', '* Next 151 s')}
      </div>
      <div class="box row" style="align-items:center;gap:20px;padding:10px 18px">${circle('91', 48)}<span class="lbl">Quality</span><span style="width:2px;height:40px;background:var(--border)"></span>${circle('35%', 48)}<div class="col" style="gap:2px"><span class="lbl">Layer 42/120</span><span class="note">ETA 02:05:00</span></div>${btn('+ Escalate to engineer', '', 'margin-left:auto')}</div>
    </div>`, true);

// ---------- L04 · Vision (W/H labels above the bead, no region box) ----------
const L04 = shell('Live prints', printTop('Vision', 'Operator', 'MO'), `<div class="row grow" style="padding:16px 24px;gap:18px">
      <div class="x grow" style="position:relative">
        ${pill('[cam] CAM-2A · Layer 42', 'position:absolute;left:14px;top:12px;background:var(--surface)')}
        <div style="position:absolute;left:38%;right:38%;top:44%;height:16%;border:3px solid var(--text);border-radius:40px;background:var(--surface)"></div>
        <div style="position:absolute;left:38%;right:38%;top:52%;border-top:3px solid var(--text)"></div>
        <div style="position:absolute;left:55%;top:44%;height:16%;border-left:3px solid var(--text)"></div>
        ${pill('[■] W 36.4 mm', 'position:absolute;left:22%;top:30%;background:var(--surface)')}
        ${pill('[■] H 14.8 mm', 'position:absolute;left:58%;top:30%;background:var(--surface)')}
      </div>
      <div class="col" style="width:300px">
        <div class="box col" style="gap:10px"><span class="lbl">Measured vs target</span><div class="row" style="justify-content:space-between"><span>Width 36.4 / 40</span><span class="note">! −9 %</span></div><div class="row" style="justify-content:space-between"><span>Height 14.8 / 15</span><span class="note">o −1 %</span></div></div>
        <div class="box col" style="gap:6px"><span class="lbl">Width · last 10 layers</span>${limitChart(true, true)}</div>
        <div class="box col" style="gap:10px"><div class="row" style="justify-content:space-between"><span class="lbl">Confidence</span><span>93 %</span></div>${bar(93, true, 12)}<div class="row" style="justify-content:space-between;align-items:center"><span class="lbl">Show overlay</span><span class="pill" style="width:52px;justify-content:flex-end">o</span></div></div>
        <span class="btn" style="margin-top:auto">Flag as artifact</span>
      </div>
    </div>`, true);

// ---------- L05 · Trends (x-axis = layers, event markers, AI prediction) ----------
const sig = (name, on) => `<div class="row" style="gap:10px"><span class="chk"${on ? ' style="background:var(--text)"' : ''}></span><span${on ? ' class="lbl"' : ''}>${name}</span></div>`;
const L05 = shell('Live prints', printTop('Trends'), `<div class="row grow" style="padding:24px;gap:24px">
      <div class="box col" style="width:240px;gap:14px;align-self:flex-start">
        <span class="h2">Signals</span>
        ${['Material temp', 'Pump speed', 'Pump power', 'Print speed'].map((s) => sig(s)).join('')}${sig('Layer width', true)}${sig('Layer height')}${sig('Interlayer delay')}
      </div>
      <div class="col grow">
        <div class="row" style="gap:10px;align-items:center"><span class="h2" style="margin-right:auto">Layer width</span>${pill('5 m')}${pill('15 m')}${pill('1 h', 'background:var(--text);color:var(--surface)')}${pill('Whole print')}${pill('Custom')}${btn('Download view (CSV)')}</div>
        <div class="box grow" style="padding:24px 24px 34px">
          <div style="position:absolute;left:24px;right:24px;top:22%;bottom:42%;border-top:2px dashed var(--text-muted);border-bottom:2px dashed var(--text-muted)"></div>
          <svg class="squiggle" viewBox="0 0 800 360" preserveAspectRatio="none" style="position:relative"><path d="M0 170 Q60 150 120 175 T240 160 T360 180 T480 170 T560 200 T620 250 T660 262" fill="none" stroke="#1C1E21" stroke-width="3"/><path d="M660 262 Q720 220 800 175" fill="none" stroke="#1C1E21" stroke-width="3" stroke-dasharray="10 8"/><path d="M600 0V360M650 0V360" stroke="#5F6368" stroke-width="2" stroke-dasharray="4 6"/></svg>
          <span class="anno" style="left:40%;top:14px">markers: Alert raised · Pump adjusted</span>
          <span class="anno" style="right:24px;top:52px">AI prediction (dashed)</span>
          <span class="note" style="position:absolute;left:24px;right:24px;bottom:8px;display:flex;justify-content:space-between"><span>L10</span><span>L20</span><span>L30</span><span>L40</span><span>Layer</span></span>
        </div>
        <div class="row">${kpi('Min', '36.4')}${kpi('Max', '40.8')}${kpi('Avg', '38.7')}${kpi('σ', '1.1')}</div>
      </div>
    </div>`, true);

// ---------- L06 · AI Recommendations (detail left, queue right) ----------
const L06 = shell('Live prints', printTop('AI'), `<div class="row grow" style="padding:24px;gap:24px">
      <div class="box col grow" style="gap:14px;padding:26px">
        <div class="row" style="align-items:center">${pill('* AI')}<span class="note">Suggested 14:33 · Layer 42</span></div>
        <span class="h">Pump speed 246 → 262 RPM</span>
        <div class="row" style="align-items:center;gap:12px"><span class="note">Confidence</span><div class="bar" style="width:220px;height:12px"><div class="bar bar-dark" style="width:87%;height:12px"></div></div><span class="lbl">87 %</span></div>
        <div class="box grow col" style="gap:6px"><div class="row" style="justify-content:space-between"><span class="h2">Predicted effect</span><span class="note">back to 39.6 mm in 3 layers</span></div><svg class="squiggle" viewBox="0 0 600 160" preserveAspectRatio="none"><path d="M0 40 L120 50 L240 80 L300 120" fill="none" stroke="#1C1E21" stroke-width="3"/><path d="M300 120 Q400 70 600 45" fill="none" stroke="#1C1E21" stroke-width="3" stroke-dasharray="10 8"/><path d="M300 0V160" stroke="#1C1E21" stroke-width="2"/></svg></div>
        <span class="h2">Why</span>${lines(85, 75, 60)}
        <div class="row" style="align-items:center">${btn('Accept', 'btn-fill')}${btn('Modify')}${btn('Reject', '', 'border-style:dashed')}<span class="note" style="margin-left:auto">applies at next layer · logged</span></div>
      </div>
      <div class="col" style="width:360px">
        <div class="row" style="gap:0;border-bottom:2px solid var(--text)"><span class="tab tab-on">Pending</span><span class="tab">Accepted</span><span class="tab">Rejected</span><span class="tab">Manual</span></div>
        <div class="box col" style="gap:8px;border-width:3px"><div class="row" style="justify-content:space-between"><span class="lbl">Pump speed +16 RPM</span><span class="note">* 87 %</span></div>${bar(40)}</div>
        <div class="col center grow"><span class="note">No other suggestions</span></div>
        ${btn('Adjust without AI')}
      </div>
    </div>`, true);

// ---------- L07 · Session Report (alerts overlaid on the chart) ----------
const L07 = shell('Sessions', topbar('Session report', 'Manager', 'JB'), `<div class="col grow" style="padding:22px 28px;gap:18px">
      <div class="row" style="align-items:flex-end">
        <div class="col" style="gap:4px"><span class="note" style="text-decoration:underline">Sessions &gt; S-1008-02</span><span class="h">WP-03 · Gantry-02</span><div class="row" style="gap:10px;align-items:center"><span class="note">Oct 8 · 2 h 05 m</span>${pill('o Completed')}</div></div>
        <div class="row" style="margin-left:auto">${btn('Share link', '', 'border-style:dashed')}${btn('CSV')}${btn('JSON')}${btn('Export PDF report', 'btn-fill')}</div>
      </div>
      <div class="row">${kpi('Quality', 94)}${kpi('Layers', '120/120')}${kpi('Alerts', 5)}${kpi('Adjustments', 6)}${kpi('* AI accuracy', '91 %')}</div>
      <div class="box col" style="height:250px;gap:6px">
        <div class="row" style="justify-content:space-between"><span class="h2">Layer width</span><span class="note">— observed · - - AI · ▲ / o alerts</span></div>
        <svg class="squiggle" viewBox="0 0 800 160" preserveAspectRatio="none" style="flex:1"><path d="M0 60 Q60 50 120 62 T200 110 T280 60 T400 58 T560 55 T800 58" fill="none" stroke="#1C1E21" stroke-width="3"/><path d="M0 55 Q60 58 120 58 T200 95 T280 62 T400 54 T560 60 T800 54" fill="none" stroke="#1C1E21" stroke-width="2.5" stroke-dasharray="9 7"/>
          <path d="M150 12V160M190 12V160M205 12V160M330 12V160M650 12V160" stroke="#5F6368" stroke-width="2" stroke-dasharray="3 5"/>
          ${[150, 650].map((x) => `<circle cx="${x}" cy="10" r="7" fill="#5F6368"/>`).join('')}${[190, 205, 330].map((x) => `<path d="M${x} 2L${x + 8} 16H${x - 8}Z" fill="#1C1E21"/>`).join('')}</svg>
      </div>
      <div class="row grow">
        <div class="box col box-dash" style="width:440px;gap:12px"><span class="lbl">* AI summary (editable)</span>${lines(95, 92, 88, 70)}</div>
        <div class="box grow col" style="gap:12px">
          <div class="row" style="gap:0;border-bottom:2px solid var(--text)"><span class="tab tab-on">Adjustments (6)</span><span class="tab">Parameters used</span></div>
          ${lines(100, 100, 100, 100, 100)}
        </div>
      </div>
    </div>`);

const pages = [
  ['L01-login-mfa', 'L01', 'Login + MFA', '/login, /login/verify', 'US-01', L01],
  ['L02-dashboard', 'L02', 'Home / Dashboard', '/dashboard', 'US-03,04,06', L02],
  ['L03-live-monitor', 'L03', 'Live Print Monitor', '/prints/:jobId/live', 'US-03,04,06,07', L03],
  ['L04-vision', 'L04', 'Vision', '/prints/:jobId/vision', 'US-05,07', L04],
  ['L05-trends', 'L05', 'Trends', '/prints/:jobId/trends', 'US-08', L05],
  ['L06-ai-recommendations', 'L06', 'AI Recommendations', '/prints/:jobId/ai', 'US-09,10,11', L06],
  ['L07-session-report', 'L07', 'Session Report', '/sessions/:sessionId/report', 'US-12,13', L07],
];
for (const [file, id, title, route, us, body] of pages) fs.writeFileSync(`src/lofi/${file}.html`, page(id, title, route, us, body));
console.log(`Wrote ${pages.length} lo-fi sheets to src/lofi/`);
